script:
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
$ProgressPreference='SilentlyContinue'
$paths=@('C:\Program Files\Google\Chrome\Application\chrome.exe',(Join-Path $env:LOCALAPPDATA 'Google\Chrome\Application\chrome.exe'))
foreach($p in $paths){if(Test-Path -LiteralPath $p){@{browser=$p;version=(Get-Item -LiteralPath $p).VersionInfo.ProductVersion}|ConvertTo-Json -Compress}}
$i=Get-Process -Id 7016 -ErrorAction SilentlyContinue
if($i){@{knownInstallerPID=$i.Id;windowTitle=$i.MainWindowTitle}|ConvertTo-Json -Compress}
$l=Join-Path $env:LOCALAPPDATA 'EasyCV-Downloads-20261102-Chrome\chrome-msi-install.log'
if(Test-Path -LiteralPath $l){Get-Content -LiteralPath $l -Tail 18 | Select-String 'Installation|Product:|Return value 3|error status|错误状态' | ForEach-Object {$_.Line}}
